import json
import heapq
import sys

def solve():
    args = json.loads(sys.argv[1])
    map_id = args.get('map_id')
    start_x = int(args.get('start_x'))
    start_y = int(args.get('start_y'))
    end_x = int(args.get('end_x'))
    end_y = int(args.get('end_y'))

    width, height = 30, 36
    if map_id == '0_60':
        width, height = 28, 28
    elif map_id == '0_61':
        width, height = 30, 30

    blocked = set()

    if map_id == '0_59':
        for y in range(16, 20):
            blocked.add((22, y))
            blocked.add((23, y))
        for y in range(29, 36):
            blocked.add((16, y))
        for y in [28, 30, 31, 32]:
            blocked.add((19, y))
        for y in range(2, 12):
            blocked.add((12, y))
            blocked.add((13, y))
        for y in range(8, 12):
            blocked.add((18, y))
            blocked.add((19, y))
        blocked.add((10, 21))
        blocked.add((6, 19))
        for x in range(11, 20):
            blocked.add((x, 20))

    elif map_id == '0_60':
        for x in range(0, 10):
            for y in range(21, 28):
                blocked.add((x, y))

    elif map_id == '0_61':
        for x in [27, 28, 29, 30, 31, 32, 33]:
            blocked.add((x, 21))
        blocked.add((25, 12))

    start = (start_x, start_y)
    end = (end_x, end_y)

    if start == end:
        print(json.dumps([]))
        return

    queue = []
    heapq.heappush(queue, (0, start, []))
    visited = set()
    visited.add(start)

    while queue:
        cost, curr, path = heapq.heappop(queue)
        cx, cy = curr

        if curr == end:
            print(json.dumps(path))
            return

        for dx, dy, move in [(0, -1, 'Up'), (0, 1, 'Down'), (-1, 0, 'Left'), (1, 0, 'Right')]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < width and 0 <= ny < height:
                if (nx, ny) not in blocked and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    h = abs(nx - end_x) + abs(ny - end_y)
                    heapq.heappush(queue, (len(path) + 1 + h, (nx, ny), path + [move]))

    print(json.dumps({"error": "No path found"}))

solve()
